return function(params, ctx)
  local extraction = ctx.run_agent { name = 'extract', prompt = params.prompts.extract, model = params.models.extract, input = ctx.input, controls = {temperature = 0, max_tokens = 1000} }
  if extraction.output == nil then return {delivered = false} end
  local review = ctx.run_agent { name = 'review', prompt = params.prompts.review, model = params.models.review, input = extraction.output, tools = {}, controls = {temperature = 0, max_tokens = 1000} }
  return {answer = review.output, findings = extraction.output}
end
